// Independent higher-precision KPM equations and Taylor quantum propagator.
// No CUDA headers/source solver implementation or GPU context.
#include <complex>
#include <vector>
#include <fstream>
#include <cmath>
#include <cstdio>
#include <cfloat>
#include <stdexcept>
#include <string>
using F=long double;using Z=std::complex<F>;using V=std::vector<Z>;
constexpr Z I(0,1);
template<class T>std::vector<T>read(std::ifstream&f,size_t n){std::vector<T>a(n);f.read((char*)a.data(),n*sizeof(T));if(!f)throw std::runtime_error("short fixture");return a;}
struct Problem{int n,maxn,ne,nt,M,R,nl;bool vac0,vac,msd,spin,ldos;F volume,emax;std::vector<int>nn,neighbors,locals;std::vector<double>energy,time,potential,hr,hi,dx;std::vector<V>states;std::vector<Z>H,C,J;};
Problem load(std::string path){std::ifstream f(path,std::ios::binary);auto h=read<int>(f,12);auto s=read<double>(f,2);Problem p;p.n=h[0];p.maxn=h[1];p.ne=h[2];p.nt=h[3];p.M=h[4];p.R=h[5];p.vac0=h[6];p.vac=h[7];p.msd=h[8];p.spin=h[9];p.ldos=h[10];p.nl=h[11];p.volume=s[0];p.emax=s[1];p.energy=read<double>(f,p.ne);p.time=read<double>(f,p.nt);p.locals=read<int>(f,p.nl);p.nn=read<int>(f,p.n);p.neighbors=read<int>(f,p.n*p.maxn);p.potential=read<double>(f,p.n);p.hr=read<double>(f,p.n*p.maxn);p.hi=read<double>(f,p.n*p.maxn);p.dx=read<double>(f,p.n*p.maxn);for(int r=0;r<p.R;r++){auto re=read<double>(f,p.n),im=read<double>(f,p.n);V state(p.n);for(int k=0;k<p.n;k++)state[k]=Z(re[k],im[k]);p.states.push_back(state);}if(p.n<=257){p.H.assign(p.n*p.n,0);p.C=p.H;p.J=p.H;for(int i=0;i<p.n;i++){p.H[i*p.n+i]=p.potential[i]/p.emax;for(int k=0;k<p.nn[i];k++){int at=i*p.maxn+k,j=p.neighbors[at];Z z(p.hr[at],p.hi[at]);p.H[i*p.n+j]+=z/p.emax;p.C[i*p.n+j]-=z*F(p.dx[at])/p.emax;p.J[i*p.n+j]-=I*z*F(p.dx[at]);}}}return p;}
V apply(const Problem&p,const V&x,const std::vector<Z>*matrix=nullptr){V y(p.n);if(matrix){for(int i=0;i<p.n;i++)for(int j=0;j<p.n;j++){Z a=(*matrix)[i*p.n+j];if(a!=Z(0))y[i]+=a*x[j];}}else{for(int i=0;i<p.n;i++){Z v=F(p.potential[i])*x[i];for(int k=0;k<p.nn[i];k++){int at=i*p.maxn+k;v+=Z(p.hr[at],p.hi[at])*x[p.neighbors[at]];}y[i]=v/p.emax;}}return y;}
Z dot(const V&a,const V&b){Z s=0;for(size_t i=0;i<a.size();i++)s+=std::conj(a[i])*b[i];return s;}
V moments(const Problem&p,const V&left,const V&right){V out(p.M);V a=right,b=apply(p,right,p.H.empty()?nullptr:&p.H);out[0]=dot(left,a);out[1]=dot(left,b);for(int k=2;k<p.M;k++){V c=apply(p,b,p.H.empty()?nullptr:&p.H);for(int j=0;j<p.n;j++)c[j]=F(2)*c[j]-a[j];out[k]=dot(left,c);a.swap(b);b.swap(c);}return out;}
// Evaluate exact matrix exponential / derivation with an independent Taylor
// series, rather than source Bessel/Chebyshev propagation. Small controls only.
std::pair<V,V>propagate(const Problem&p,const V&input,F physical_time,int direction){if(p.H.empty())throw std::runtime_error("small matrix required");F tau=physical_time*p.emax;V q=input,qx(p.n),out=input,outx(p.n);Z coefficient=1;for(int k=1;k<=96;k++){V next=apply(p,q,&p.H),nextx=apply(p,qx,&p.H),c=apply(p,q,&p.C);for(int j=0;j<p.n;j++)nextx[j]+=c[j];coefficient*=(-I*F(direction)*tau)/F(k);for(int j=0;j<p.n;j++){out[j]+=coefficient*next[j];outx[j]+=coefficient*nextx[j];}q.swap(next);qx.swap(nextx);}if(direction<0)for(auto&z:outx)z=-z;return{out,outx};}
std::vector<F>density(const Problem&p,const V&mu){std::vector<F>values(p.ne);F pi=acosl(-1.L);std::vector<F>damp(p.M);for(int m=0;m<p.M;m++){F factor=1.L/F(p.M+1);damp[m]=(1.L-m*factor)*cosl(m*pi*factor)+sinl(m*pi*factor)*factor/tanl(pi*factor);}for(int e=0;e<p.ne;e++){F scaled=F(p.energy[e])/p.emax,theta=acosl(scaled),sum=mu[0].real()*damp[0];for(int m=1;m<p.M;m++)sum+=2.L*mu[m].real()*damp[m]*cosl(m*theta);values[e]=sum*2.L/(pi*p.volume*p.emax*sqrtl(1.L-scaled*scaled));}return values;}
struct Writer{std::ofstream f,states;int records=0;Writer(std::string path):f(path,std::ios::binary),states(path+".states.bin",std::ios::binary){}void state_record(int c,int kind,int r,int role,const V&v){int h[]={c,kind,r,role,int(v.size())};states.write((char*)h,sizeof h);for(auto z:v){double x=z.real();states.write((char*)&x,8);}for(auto z:v){double x=z.imag();states.write((char*)&x,8);}if(!states)throw std::runtime_error("state oracle write");}void record(int case_id,int kind,int random,int step,int orbital,const Problem&p,const V&left,const V&right){V mu=moments(p,left,right);auto values=density(p,mu);int h[]={case_id,kind,random,step,orbital,p.M,p.ne};f.write((char*)h,sizeof h);for(auto z:mu){double x=z.real();f.write((char*)&x,8);}for(auto z:mu){double x=z.imag();f.write((char*)&x,8);}for(F z:values){double x=z;f.write((char*)&x,8);}if(!f)throw std::runtime_error("oracle output");records++;}};
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("fixture directory and oracle output required");std::vector<std::string>names={"diffusive","localized","small_lattice","general_tail","spin_pairs"};Writer writer(argv[2]);F max_spin=0,max_norm=0;int initial_points=0,small_points=0;for(int c=0;c<int(names.size());c++){Problem p=load(std::string(argv[1])+"/"+names[c]+"_fixture.bin");for(int r=0;r<p.R;r++){const V&psi=p.states[r];writer.record(c,1,r,0,-1,p,psi,psi);initial_points+=p.M;if(p.n>257)continue;V Jpsi=apply(p,psi,&p.J);if(p.vac0)writer.record(c,2,r,0,-1,p,Jpsi,Jpsi);
 F previous=0,current=0;for(int step=0;step<p.nt;step++){if(p.vac){V left=propagate(p,psi,previous,-1).first,right=propagate(p,Jpsi,previous,-1).first,JL=apply(p,left,&p.J);writer.record(c,3,r,step,-1,p,right,JL);if(step==p.nt-1){writer.state_record(c,3,r,10,left);writer.state_record(c,3,r,11,right);}max_norm=std::max(max_norm,fabsl(dot(left,left).real()-dot(psi,psi).real()));}
 if(p.msd){current+=F(p.time[step]);auto u=propagate(p,psi,current,1);writer.record(c,4,r,step,-1,p,u.second,u.second);if(step==p.nt-1){writer.state_record(c,4,r,12,u.first);writer.state_record(c,4,r,13,u.second);}max_norm=std::max(max_norm,fabsl(dot(u.first,u.first).real()-dot(psi,psi).real()));}
 if(p.spin){V state=propagate(p,psi,previous,1).first,sz=state;for(int k=1;k<p.n;k+=2)sz[k]=-sz[k];writer.record(c,5,r,step,-1,p,state,sz);if(step==p.nt-1)writer.state_record(c,5,r,14,state);F omega=sqrtl(.125L*.125L+.25L*.25L+.5L*.5L),ratio=(.125L*.125L)/(omega*omega);F exact=dot(psi,psi).real()*(ratio+(1.L-ratio)*cosl(2.L*omega*previous));max_spin=std::max(max_spin,fabsl(dot(state,sz).real()-exact));}
 previous+=F(p.time[step]);small_points+=p.n;}
 }
 if(p.n<=257&&p.ldos)for(int orbital:p.locals){V local(p.n);local[orbital]=sqrtl(F(p.n));writer.record(c,6,-1,0,orbital,p,local,local);}
 }
 printf("{\"oracle_records\":%d,\"large_and_small_initial_DOS_moments\":%d,\"small_control_point_steps\":%d,\"LongDouble_mantissa_bits\":%d,\"LongDouble_storage_bytes\":%zu,\"Taylor_terms_small_controls\":96,\"analytic_spin_norm_difference\":%.20Lg,\"Taylor_unitarity_max_abs_norm_error\":%.20Lg,\"scope\":\"AllinitialDOSmoments5sourceproblems;independentdenseTaylorallsmallcontrolcorrelations/LDOS. Notalllargecorrelationtrajectories orphysicalconvergencecertificate.\"}\n",writer.records,initial_points,small_points,LDBL_MANT_DIG,sizeof(F),max_spin,max_norm);return 0;
}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
